import{_ as d,o as e,c as r,a2 as o}from"./chunks/framework.D6RJXrbK.js";const h=JSON.parse('{"title":"附录 B 术语表","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/b-glossary.md","filePath":"appendix/b-glossary.md","lastUpdated":1791513046000}'),c={name:"appendix/b-glossary.md"};function s(a,t,i,n,l,p){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="附录-b-术语表" tabindex="-1">附录 B 术语表 <a class="header-anchor" href="#附录-b-术语表" aria-label="Permalink to &quot;附录 B 术语表&quot;">​</a></h1><p>按拼音/字母顺序。括号里是本书主要讲解它的章节。</p><table tabindex="0"><thead><tr><th>术语</th><th>英文 / 代码中的名字</th><th>含义</th></tr></thead><tbody><tr><td>授权模型</td><td>authorization model</td><td>一组类型定义和条件，描述有哪些对象类型、每种类型有哪些关系、关系怎样由元组和其他关系推出。不可修改，每次写入产生一个新版本（4、5、22）</td></tr><tr><td>版本（模型）</td><td>authorization model ID</td><td>模型的 ULID；“最新模型”就是 ID 最大的那个（22）</td></tr><tr><td>元组</td><td>relationship tuple, <code>object#relation@user</code></td><td>一条事实：某个用户（或用户集）与某个对象有某种关系（6）</td></tr><tr><td>对象</td><td>object, <code>type:id</code></td><td>被授权的东西，例如 <code>document:design</code>（1、6）</td></tr><tr><td>用户 / 主体</td><td>user, subject</td><td>元组的 user 一侧：具体对象（<code>user:anne</code>）、通配符（<code>user:*</code>）或用户集（<code>group:eng#member</code>）（6）</td></tr><tr><td>用户集</td><td>userset, <code>object#relation</code></td><td>“与某对象有某关系的所有主体”，例如 <code>group:eng#member</code>（1、11）</td></tr><tr><td>通配符</td><td>typed wildcard, <code>user:*</code></td><td>某类型的所有主体，只能出现在 user 一侧（6、11）</td></tr><tr><td>隐式元组</td><td>implicit tuple</td><td><code>group:a#member@group:a#member</code> 这种“自己包含自己”的元组，总是成立，不允许写入（6、22）</td></tr><tr><td>类型限制</td><td>type restriction, directly related user types</td><td><code>define viewer: [user, group#member]</code> 方括号里的内容，规定可以直接写入哪些形态的用户（5、6）</td></tr><tr><td>重写规则</td><td>userset rewrite</td><td>关系的定义：直接赋值（this）、计算关系（computed）、元组到用户集（TTU）、并、交、差（1、4）</td></tr><tr><td>计算关系</td><td>computed userset</td><td><code>define viewer: editor</code>：同一个对象上的另一个关系（4）</td></tr><tr><td>元组到用户集</td><td>tuple to userset, TTU, <code>X from parent</code></td><td>先读 tupleset 关系找到父对象，再在父对象上求 X（4、11）</td></tr><tr><td>tupleset</td><td>tupleset</td><td>TTU 里 <code>from</code> 后面的那个关系，必须是直接关系、不能是 userset（5、6）</td></tr><tr><td>条件</td><td>condition</td><td>用 CEL 写的布尔表达式，挂在类型限制和元组上，参数来自元组或请求（14）</td></tr><tr><td>内联表达式</td><td><code>$expression</code></td><td>直接写在元组上的条件，实验特性 <code>inline_expressions</code>（14）</td></tr><tr><td>上下文元组</td><td>contextual tuples</td><td>随请求发送、只对这次请求有效的元组（13）</td></tr><tr><td>store</td><td>store</td><td>隔离单元：一组模型版本、元组、断言和变更日志（22、29）</td></tr><tr><td>Check</td><td>Check</td><td>“用户 U 与对象 O 是否有关系 R”（3、8–12）</td></tr><tr><td>BatchCheck</td><td>BatchCheck</td><td>一次请求里的多个 Check，相同的会被去重（17）</td></tr><tr><td>Expand</td><td>Expand</td><td>展开一个 <code>object#relation</code> 的一层用户集合树（16）</td></tr><tr><td>ListObjects</td><td>ListObjects</td><td>“用户 U 对哪些 T 类型的对象有关系 R”（18、19）</td></tr><tr><td>ListUsers</td><td>ListUsers</td><td>“哪些主体（按过滤器）对对象 O 有关系 R”（20）</td></tr><tr><td>断言</td><td>assertion</td><td>挂在模型版本上的期望结果，相当于模型的单元测试（23）</td></tr><tr><td>变更日志</td><td>changelog, ReadChanges</td><td>元组写入与删除的有序记录，用续读令牌消费（23）</td></tr><tr><td>续读令牌</td><td>continuation token</td><td>分页 API 返回的不透明字符串，带着它继续读下一页（21–23）</td></tr><tr><td>一致性偏好</td><td>consistency, <code>HIGHER_CONSISTENCY</code></td><td>要求跳过缓存、直接读存储（23）</td></tr><tr><td>解析器</td><td>CheckResolver</td><td>Check 的处理单元接口；多个解析器组成一个环形链（9、15）</td></tr><tr><td>LocalChecker</td><td>LocalChecker</td><td>真正按重写规则求值的解析器（9）</td></tr><tr><td>派发</td><td>dispatch</td><td>把一个子问题交给解析链（可能带缓存、限流）再求一次，例如对每个组求成员（9）</td></tr><tr><td>深度</td><td>resolution depth</td><td>一条路径上派发的次数，默认上限 25，超过报 <code>authorization_model_resolution_too_complex</code>（12）</td></tr><tr><td>环检测</td><td>cycle detection, <code>VisitedPaths</code></td><td>同一条路径上第二次遇到同一个子问题（12）</td></tr><tr><td>环标志</td><td><code>CycleDetected</code></td><td>结果来自环、而不是来自数据；交集和排除对它特殊处理（10、12）</td></tr><tr><td>路径相关</td><td><code>PathDependent</code>（mini）</td><td>自递归关系里截断环得到的 false：语义上是 false，但不能缓存（12、31）</td></tr><tr><td>短路</td><td>short-circuit</td><td>union 遇到 true、intersection 遇到 false、exclusion 遇到 base false 或 subtract true 时立即返回并取消其他分支（10）</td></tr><tr><td>不变缓存键</td><td>invariant cache key</td><td>缓存键里与子问题无关、但影响结果的部分：上下文元组和 context 的哈希（13、15）</td></tr><tr><td>缓存控制器</td><td>cache controller</td><td>根据变更日志判断缓存何时过期（23）</td></tr><tr><td>派发限流</td><td>dispatch throttling</td><td>派发次数超过阈值后放慢派发（15）</td></tr><tr><td>权重</td><td>weight</td><td>从某类用户到某个关系最多经过几条元组，∞ 表示递归（27）</td></tr><tr><td>带权图</td><td>weighted authorization model graph</td><td>由 <code>openfga/language</code> 构造的模型图，节点和边都带权重（27）</td></tr><tr><td>PathExists</td><td>PathExists</td><td>模型里是否存在从这类用户到这个关系的路径；不存在就直接返回 false（27）</td></tr><tr><td>求值策略</td><td>strategy: default / weight2 / recursive</td><td>同一个子问题的不同算法：逐个派发、两个集合求交、递归集合计算（27）</td></tr><tr><td>规划器</td><td>planner</td><td>用 Thompson 采样按子问题形状选择策略（28）</td></tr><tr><td>反向展开</td><td>reverse expand</td><td>ListObjects 的经典算法：从用户出发沿关系图反向走（18）</td></tr><tr><td>关系图的边</td><td>relationship edge</td><td>反向展开用的边：direct、TTU、computed（18）</td></tr><tr><td>需要复核</td><td><code>RequiresFurtherEval</code></td><td>反向展开经过 <code>and</code>/<code>but not</code> 得到的候选，需要用 Check 确认（18、19）</td></tr><tr><td>流水线</td><td>pipeline ListObjects</td><td>v1.22 默认的 ListObjects 实现：模型编译成 worker 数据流图（19）</td></tr><tr><td>矩阵测试</td><td>matrix tests</td><td><code>assets/tests/*.yaml</code> 中的共享测试，在所有存储上运行（0、31）</td></tr><tr><td>影子模式</td><td>shadow check</td><td>生产中用主实现返回结果、后台用新实现再算一遍并比较（31）</td></tr><tr><td>差分测试</td><td>differential testing, <code>cmd/difftest</code></td><td>随机数据上比较两个实现的所有答案（31）</td></tr><tr><td>预共享密钥</td><td>preshared key</td><td>最简单的 API 认证方式（29）</td></tr><tr><td>访问控制（实验）</td><td><code>enable-access-control</code></td><td>用一个 OpenFGA store 授权 OpenFGA 自己的 API（29）</td></tr><tr><td>实验特性</td><td><code>--experimentals</code></td><td>默认关闭（或默认开启但可配置）的新功能开关（2）</td></tr><tr><td>ULID</td><td>ULID</td><td>26 字符、按字符串排序即按时间排序的 ID（22）</td></tr><tr><td>WAL</td><td>write-ahead logging</td><td>SQLite 的日志模式：读写互不阻塞（21）</td></tr><tr><td>UDS</td><td>Unix domain socket</td><td>OpenFGA 的 HTTP 网关通过它在进程内调用 gRPC 服务（24）</td></tr><tr><td>grpc-gateway</td><td>grpc-gateway</td><td>从 protobuf 注解生成 HTTP/JSON 到 gRPC 的转换层（24）</td></tr><tr><td>解析树（mini）</td><td>explanation tree, <code>/explain</code></td><td>不短路地记录一次 Check 的每一步，用于 Playground（26）</td></tr></tbody></table>',3)])])}const m=d(c,[["render",s]]);export{h as __pageData,m as default};
